    /// 由上游 using 组合决定，调用点同时 import 两者，故此处放 System.Ole 不改变可编译性。
    /// </remarks>
    public enum CLIPBOARD_FORMAT : ushort
    {
        CF_TEXT = 1,
        CF_BITMAP = 2,
        CF_METAFILEPICT = 3,
        CF_DIB = 8,
        CF_UNICODETEXT = 13,
        CF_ENHMETAFILE = 14,
        CF_HDROP = 15,
    }
}

namespace Windows.Win32
{
    internal static partial class PInvoke
    {
        /// <summary>
        /// <c>SetEnhMetaFileBits</c>：由 EMF 字节流创建增强图元文件句柄。
        /// </summary>
        /// <remarks>
        /// 签名由上游调用点实测反推：<c>WpfOleServices.cs</c> 写作
        /// <c>HENHMETAFILE hemf = PInvoke.SetEnhMetaFileBits(buffer);</c>
        /// （只传 byte[]，长度由 CsWin32 的友好重载补 length），
        /// 原生签名为 <c>HENHMETAFILE SetEnhMetaFileBits(UINT cbBuffer, const BYTE *pbBuffer)</c>。
        /// Linux 无 GDI 图元文件：恒返回空句柄（调用方按 <c>hemf.IsNull</c> 走失败分支，
        /// 这是 Linux 上的正确取值，而不是伪造一个非空句柄）。
        /// </remarks>
        internal static Graphics.Gdi.HENHMETAFILE SetEnhMetaFileBits(byte[] buffer) => Graphics.Gdi.HENHMETAFILE.Null;
    }
}
